rules.logic:
if (element.querySelector('.custom-pin-actions')) return;

var actionsBar = document.createElement('div');
actionsBar.className = 'custom-pin-actions';
actionsBar.style.cssText = 'display:flex;justify-content:flex-end;gap:6px;padding:8px 10px;pointer-events:auto;';

var shareBtn = document.createElement('button');
shareBtn.setAttribute('aria-label', 'Share pin');
shareBtn.type = 'button';
shareBtn.style.cssText = 'display:flex;align-items:center;justify-content:center;width:32px;height:32px;border:none;background:rgba(255,255,255,0.9);border-radius:50%;cursor:pointer;padding:0;box-shadow:0 1px 4px rgba(0,0,0,0.15);transition:background 0.2s;';
shareBtn.onmouseenter = function() { this.style.background = 'rgba(230,0,35,0.9)'; this.querySelector('svg').style.fill = 'white'; };
shareBtn.onmouseleave = function() { this.style.background = 'rgba(255,255,255,0.9)'; this.querySelector('svg').style.fill = '#333'; };

var shareSvg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
shareSvg.setAttribute('width', '16');
shareSvg.setAttribute('height', '16');
shareSvg.setAttribute('viewBox', '0 0 24 24');
shareSvg.setAttribute('fill', '#333');
shareSvg.innerHTML = '<path d="M18 16.08c-.76 0-1.44.3-1.96.77L8.91 12.7c.05-.23.09-.46.09-.7s-.04-.47-.09-.7l7.05-4.11c.54.5 1.25.81 2.04.81 1.66 0 3-1.34 3-3s-1.34-3-3-3-3 1.34-3 3c0 .24.04.47.09.7L8.04 9.81C7.5 9.31 6.79 9 6 9c-1.66 0-3 1.34-3 3s1.34 3 3 3c.79 0 1.5-.31 2.04-.81l7.12 4.16c-.05.21-.08.43-.08.65 0 1.61 1.31 2.92 2.92 2.92s2.92-1.31 2.92-2.92-1.31-2.92-2.92-2.92z"/>';
shareBtn.appendChild(shareSvg);

var downloadBtn = document.createElement('button');
downloadBtn.setAttribute('aria-label', 'Download pin');
downloadBtn.type = 'button';
downloadBtn.style.cssText = 'display:flex;align-items:center;justify-content:center;width:32px;height:32px;border:none;background:rgba(255,255,255,0.9);border-radius:50%;cursor:pointer;padding:0;box-shadow:0 1px 4px rgba(0,0,0,0.15);transition:background 0.2s;';
downloadBtn.onmouseenter = function() { this.style.background = 'rgba(230,0,35,0.9)'; this.querySelector('svg').style.fill = 'white'; };
downloadBtn.onmouseleave = function() { this.style.background = 'rgba(255,255,255,0.9)'; this.querySelector('svg').style.fill = '#333'; };

var downloadSvg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
downloadSvg.setAttribute('width', '16');
downloadSvg.setAttribute('height', '16');
downloadSvg.setAttribute('viewBox', '0 0 24 24');
downloadSvg.setAttribute('fill', '#333');
downloadSvg.innerHTML = '<path d="M19 9h-4V3H9v6H5l7 7 7-7zM5 18v2h14v-2H5z"/>';
downloadBtn.appendChild(downloadSvg);

var pinLink = element.querySelector('[data-test-id="deeplink-wrapper"] a');
var href = pinLink ? pinLink.href : '';
var imgEl = element.querySelector('[data-test-id="non-story-pin-image"] img');
var imgUrl = imgEl ? imgEl.src.replace('/236x/', '/1200x/') : '';

shareBtn.onclick = function(e) {
  e.preventDefault();
  e.stopPropagation();
  if (navigator.share) {
    navigator.share({ title: 'Pinterest Pin', url: href }).catch(function(){});
  } else {
    navigator.clipboard.writeText(href).then(function(){
      shareBtn.title = 'Link copied!';
      setTimeout(function(){ shareBtn.title = ''; }, 1500);
    });
  }
};

downloadBtn.onclick = function(e) {
  e.preventDefault();
  e.stopPropagation();
  if (imgUrl) {
    var a = document.createElement('a');
    a.href = imgUrl;
    a.download = 'pin-image.jpg';
    a.target = '_blank';
    a.rel = 'noopener noreferrer';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  }
};

actionsBar.appendChild(shareBtn);
actionsBar.appendChild(downloadBtn);

var imageWrapper = element.querySelector('.PinCard__imageWrapper');
if (imageWrapper) {
  imageWrapper.style.position = 'relative';
  imageWrapper.appendChild(actionsBar);
} else {
  var pinWrapper = element.querySelector('[data-test-id="pinWrapper"]');
  if (pinWrapper) {
    pinWrapper.style.position = 'relative';
    pinWrapper.appendChild(actionsBar);
  }
}
